import{_ as t,o as e,c as a,ag as o}from"./chunks/framework.DaAXJYxM.js";const l=JSON.parse('{"title":"第73章 七十多天","description":"","frontmatter":{},"headers":[],"relativePath":"第73章_七十多天.md","filePath":"第73章_七十多天.md"}'),_={name:"第73章_七十多天.md"};function r(n,p,s,u,c,i){return e(),a("div",null,[...p[0]||(p[0]=[o('<h1 id="第73章-七十多天" tabindex="-1">第73章 七十多天 <a class="header-anchor" href="#第73章-七十多天" aria-label="Permalink to &quot;第73章 七十多天&quot;">​</a></h1><p>她这一次断了七十多天。</p><p>四月十二号晚上，她发了一句。</p><p>她说，我下周交作品集，交完还要跑一个展，我这两个月可能上不了。</p><p>我说，多久。</p><p>她说，我不知道。</p><p>她说，你别数。</p><p>我说，我不数。</p><p>她说，你肯定数。</p><p>我说，我不写下来。</p><p>她说，行。</p><p>她说，那我先下了。</p><p>四月十二号以后，那个号就没有亮过。</p><p>高一那次，五天。</p><p>高二那次，四十九天。</p><p>高三那年，四十七天。</p><p>这次是七十多天。</p><p>我这次没有数。</p><p>我不是在吹这个。</p><p>我是真的没有数。</p><p>我一开始还记日期，记到五月就停了。</p><p>停的原因很实在：我算出来，我记这个日期，除了让我今天什么都没干成以外，它没有任何别的用处。</p><p>所以我把它划掉了。</p><p>我在本子上写：从今天起我不数。</p><p>写完之后我发现我这一辈子第一次做了这件事。</p><p>我以前所有的力量都来自数。</p><p>数到第几天，还剩几天，一年能几句话，三百六十个小时。</p><p>我不数了以后，我愣了一下。</p><p>我以为我会垮。</p><p>结果我那天照常上课，照常去实验室，照常吃饭。</p><p>我照常活。</p><p>五月我们那个组要交一个东西。</p><p>组里四个人，有一个女生坐我前面。</p><p>我们那一个月经常留到很晚。</p><p>她做事很快，她写代码的时候嘴里会出声，很小声地念。</p><p>她笑的时候左边有一个豁口，是很小的一颗牙歪了。</p><p>有一天我们弄到十一点多。</p><p>我们下楼，外面在下雨。</p><p>我们两个在门厅站着等雨。</p><p>她在那里翻包，翻出一包纸巾，抽了一张给我。</p><p>她说，你眼镜上全是水。</p><p>我说，哦，谢谢。</p><p>她开始讲一件很小的事，讲她们宿舍养了一盆绿萝，讲那盆绿萝被她浇死了两次，浇死的说法是&quot;喝多了&quot;。</p><p>我站在那里听她讲一盆绿萝。</p><p>雨下了十一分钟。</p><p>十一分钟里我笑得比那年三月加起来都多。</p><p>然后我在走出门厅那一步，忽然停了。</p><p>因为我意识到了一件事。</p><p>我在高兴。</p><p>我在一个下雨的晚上，跟一个人站在一起，我在高兴。</p><p>而我已经五十一天没有听见她的消息。</p><p>那一瞬间我脑子里第一个念头，是一个很坏的东西。</p><p>坏的地方在于它非常清楚。</p><p>我想的是：原来这一段是可以过去的。</p><p>我那天夜里三点没睡。</p><p>我一直在处理这一句。</p><p>我想到第五遍，我明白过来我在难受什么。</p><p>我难受的不是我喜欢上了别人。</p><p>那十一分钟里什么都还没发生，我连她的姓都得想一下。</p><p>我难受的是，我发现我等不到她，这件事本身，不再疼了。</p><p>我这几年所有的痛，全部建立在一件事上：我会一直疼。</p><p>我拿这个疼证明了很多东西。</p><p>我证明我在等她是对的。我证明我这一年三百六十个小时是值得的。我证明她欠我的那一笔是真的存在。</p><p>五月十九号那天夜里，我发现那个疼会自己停。</p><p>那我这几年就只剩一句话了。</p><p>我坐在那儿，把十二月九号我跟她讲的那一句翻出来。</p><p>我说的是：你要是不回来，我这辈子就再也不会对谁掏心里的话了。</p><p>那天夜里我在本子上，把这一句自己批了一遍。</p><p>我批的是：</p><p>这句是假的。</p><p>这块东西它自己会长。</p><p>它不缺使用者。</p><p>它缺的是我敢不敢给出去。</p><p>我算过的那三百六十个小时、那七千六百五十句话，全部是在替我买一样东西——买一个&quot;我给了，是别人不要&quot;的凭证。</p><p>五月那十一分钟，那个凭证作废了。</p><p>第二天我做了一件事。</p><p>我照常去实验室。</p><p>她坐我前面，她回头问我上周那个函数怎么改。</p><p>我讲完了。</p><p>她说明白了，她笑了一下，那个豁口在那儿。</p><p>她说，上周那个雨下得好大，你后来怎么跑那么快。</p><p>我说，我赶着回去锁门。</p><p>她说，你这个人真没劲。</p><p>我说，对。</p><p>她转回去了。</p><p>那天我们什么都没有发生。</p><p>那天以后也什么都没有发生。</p><p>第三周我们那个组解散，各人去做自己的毕设方向。</p><p>我们后来在食堂碰见一次，她跟我打了个招呼，走了。</p><p>我这一辈子没有跟她说过一句跟绿萝以外有关的话。</p><p>我不打算跟任何人解释这件事。</p><p>因为解释的时候，一定会有一个人问我：那你为什么不说出来。</p><p>我说出来干什么。</p><p>我说给她听，等于我把这件事变成她的责任。</p><p>她那天晚上就得决定她要不要生气，要不要难受，要不要安慰我，要不要怀疑自己。</p><p>而这些里面没有一样是她该担的。</p><p>所以我不讲。</p><p>我这边把这件事按下去，我这边自己处理。</p><p>这也意味着，她永远没法核验。</p><p>而她没法核验，它在她那边就从来没有存在过。</p><p>我承认这一点的时候，我知道这个结构里我最难看的地方在哪儿。</p><p>我用&quot;不给她添麻烦&quot;这个说法，包住了一件我根本不想跟她讲的事。</p><p>这两件事同时成立。</p><p>她第七十四天回来。</p><p>那天是六月二十四号，晚上十一点零六。</p><p>屏幕上跳进来一句。</p><p>她说，我活过来了。</p><p>后面跟了一个很难看的表情。</p><p>我说，多久了。</p><p>她说，你别算。</p><p>我说，七十多天。</p><p>她说，你看。</p><p>我说，我算完了我不写。</p><p>她说，那你今天干什么了。</p><p>我说，我在洗杯子。</p><p>她说，你洗杯子洗到十一点？</p><p>我说，我洗了很久，我今天想干净一点。</p><p>她没问为什么。</p><p>她隔了一会儿，回了一句。</p><p>她说，我这七十多天里想明白一件事。</p><p>我说，你说。</p><p>她说，你那句&quot;你再也不会对谁掏心&quot;，我想明白了。</p><p>我坐在那儿。</p><p>我说，你怎么想的。</p><p>她说，我那天不接你，是因为我一接，我就得说&quot;我也会&quot;。</p><p>她说，我不会。</p><p>她说，我这七十多天里，我忙起来有一整个星期我没想起你。</p><p>她说，我今天回来，我先跟你讲这个。</p><p>我说，你为什么要讲。</p><p>她说，因为我不想你以后拿你那句来跟我算。</p><p>她说，你现在知道我是什么样的人了。</p><p>那晚我们说了四十分钟。</p><p>她讲的全是作品集、展览、她那个导师把她的图全部否了。</p><p>一次也没提那七十多天。</p><p>我一次也没提五月那十一分钟。</p><p>那天夜里我在那本单独的本子上，写了一行。</p><p>我写：我们两个都在同一晚上，把最该讲的那一句收进了本子里。</p><p>我写完，把本子推进抽屉最里面。</p><p>那个抽屉我后来再也没打开过。</p>',139)])])}const q=t(_,[["render",r]]);export{l as __pageData,q as default};
